"""Package inspected native views and receipts; does not declare tests passed."""
import hashlib,html,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'ada_run/ca-curation';DEST=ROOT/'doc/book/iterations/2026-10-23-ca-curation'
def read(name):return json.loads((OUT/name).read_text(encoding='utf8'))
def main():
    for name in ['publish.json','editor-checks.json','gallery-checks.json','native-final.json','circulation.json']:
        assert read(name)['passed'],name
    DEST.mkdir(parents=True,exist_ok=True)
    for image in OUT.glob('ca-*.png'):
        target=DEST/image.name
        if 'baseline' not in image.name and (not target.exists() or image.read_bytes()!=target.read_bytes()):shutil.copy2(image,target)
    originals=read('inventory.json');rooms=json.loads((ROOT/'commons/void/rooms.json').read_text(encoding='utf8'))
    cards=[]
    for f in originals:
        i=f['floor'];title=rooms['floors'][i]['map'].replace('CA_','').replace('_',' ')
        cards.append(f'<article id="floor-{i}"><a href="http://localhost:3003/lab-editor?mode=void&amp;floor={i}"><img loading="lazy" src="ca-{i}-overview.png" alt="Native Godot view of {html.escape(title)}"/></a><div><span>{i:03d} / {len(f["artifacts"])} originals</span><h2>{html.escape(title)}</h2><a href="http://localhost:3003/lab-editor?mode=void&amp;floor={i}">Arrange this floor →</a></div></article>')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CA / local rule, architectural consequence</title>
<style>body{margin:0;background:#15191e;color:#efeae5;font:17px/1.5 system-ui}main{max-width:1400px;margin:auto;padding:36px 28px}a{color:#ff95c8}header{max-width:980px;margin:30px 0 48px}h1{font-size:clamp(34px,5vw,70px);line-height:1.05;font-weight:550;margin:12px 0 28px}h2{font-size:24px;margin:6px 0}.eyebrow,span{color:#f18dbb;font:13px/1.4 monospace;letter-spacing:.06em}p{max-width:880px;color:#c7c3c4}.hero{width:100%;display:block;border:1px solid #48505a}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px 20px;margin-top:44px}article{background:#20262e}article img{display:block;width:100%}article div{padding:20px}footer{border-top:1px solid #4a4e54;margin-top:48px;padding-top:20px;color:#b9b5b8}@media(max-width:700px){main{padding:20px}.grid{grid-template-columns:1fr}}</style>
<main><header><div class="eyebrow">ADA / VOID / CELLULAR AUTOMATA / 23 OCTOBER 2026</div><h1>A local rule.<br>A room that answers.</h1><p>Eight main-tower floors, all 43 existing originals, and one new architectural receiver. These are native Godot views of the current arrangement.</p><p>The sixteen-metre wall reads the same 32 × 24 history as the original desk and floor. STEP, RUN, SEED and the carried point alter the original automaton; the wall has no separate solver or clock. Its first 23 generations are computed by that solver at entry.</p><p><a href="http://localhost:3003/lab-editor?mode=void&amp;floor=109">Open the architectural comparison →</a> · <a href="http://localhost:3003/lab-editor?mode=void&amp;floor=103">Start with the neighbourhood study →</a></p></header><img class="hero" src="ca-109-overview.png" alt="The original rule explorer and its architectural history receiver"><p>Live pink cells, an off-white selected address, black steel supports. The same stored history appears at the desk, underfoot and across the room.</p><section class="grid">'''+''.join(cards)+'''</section><footer><p>Checked on the actual 42 × 18 metre main floors using native desktop input and synthetic tracked VR input. Physical headset comfort has not been tested. All original occurrences remain; fixtures and the new receiver are editable.</p><p>The editor displays exported geometry snapshots. The live algorithms run in Godot. The SIR solver keeps its full 64³ state; its occupied-cell display is capped at 4096 and reports the full counts. The original Clockmaker is a static ornamental construction. Collecting basins and the laboratory's authored lower steps extend below the slab.</p></footer></main></html>'''
    (DEST/'index.html').write_text(page,encoding='utf8')
    files=['commons/void/rooms.json','commons/void/catalog.json','commons/void/floor_content.gd','commons/void/ca_sir_live.gd','commons/void/ca_crack_live.gd','commons/void/ca_life_controls.gd','commons/void/ca_history_controls.gd','commons/void/ca_curated_door.gd','commons/void/ca_history_wall.gd','commons/managers/CatalystCapabilityManager.gd','addons/godot-xr-tools/functions/function_pickup.gd']
    files+=['commons/hazards/becoming_catalyst/capacity_bracelet/capacity_bracelet.gd','commons/hazards/becoming_catalyst/capacity_bracelet/bracelet_handle.gd']
    receipt=dict(passed=True,scope='CA functional integration and first spatial curation; not a whole-spine acceptance',retained_originals=43,new_live_receivers=1,floors=list(range(103,111)),publish=read('publish.json'),editor=read('editor-checks.json'),gallery=read('gallery-checks.json'),native_final=read('native-final.json'),circulation=read('circulation.json'),source_hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in files},limitations=['Physical headset not tested.','Static editor snapshots are not live simulation.','Original ornamental/static specimens remain intentionally static.','SIR display is capped at4096 occupied addresses; all262144 original states are simulated.','Only CA floors103–110 have been curated in this task; other spine sequences are not certified.'])
    (OUT/'review.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf8')
    print(DEST/'index.html')
if __name__=='__main__':main()
